// The website's Cloudflare Worker ("agi-website"): serves the site's files with
// the security rules from _headers, and the estimate assistant under /api/estimate.
// assets.gen.mjs is generated by `npm run build` from the Next.js output (out/).
import { FILES, RULES } from './assets.gen.mjs';
import { handleEstimator } from './estimator.mjs';
import { serveFilm, isMediaPath } from './film.mjs';

export { EstimatorStore } from './store.mjs';

const BIN = {};
function bytes(p) {
  return (BIN[p] ||= Uint8Array.from(atob(FILES[p].b64), (c) => c.charCodeAt(0)));
}
function matches(pattern, p) {
  return pattern.endsWith('*') ? p.startsWith(pattern.slice(0, -1)) : p === pattern;
}

function headersFor(p) {
  const headers = new Headers();
  for (const r of RULES) if (r.pattern === '/*' || matches(r.pattern, p)) for (const [k, v] of r.headers) headers.set(k, v);
  return headers;
}

// Next.js writes one or two small scripts inside each page. The build records their
// fingerprints; the security rules then allow exactly those scripts, nothing else.
function allowPageScripts(headers, file) {
  const csp = headers.get('Content-Security-Policy');
  if (!csp || !file.scriptHashes) return;
  const extra = file.scriptHashes.map((h) => `'sha256-${h}'`).join(' ');
  headers.set('Content-Security-Policy', csp.replace(/script-src ([^;]*)/, (_, list) => `script-src ${list} ${extra}`));
}

function serveFile(request, url) {
  if (request.method !== 'GET' && request.method !== 'HEAD') {
    return new Response('Method not allowed', { status: 405, headers: { Allow: 'GET, HEAD' } });
  }
  let p = decodeURIComponent(url.pathname);
  if (p.endsWith('/')) p += 'index.html';
  if (!FILES[p] && FILES[`${p}.html`]) p += '.html';
  let status = 200;
  if (!FILES[p]) {
    if (!FILES['/404.html']) {
      const headers = headersFor(p);
      headers.set('Content-Type', 'text/plain; charset=utf-8');
      return new Response('Page not found', { status: 404, headers });
    }
    p = '/404.html';
    status = 404;
  }
  const file = FILES[p];
  const headers = headersFor(p);
  allowPageScripts(headers, file);
  headers.set('Content-Type', file.type);
  if (status === 404) headers.set('Cache-Control', 'no-store');
  if (!headers.has('Cache-Control')) headers.set('Cache-Control', 'public, max-age=0, must-revalidate');
  return new Response(request.method === 'HEAD' ? null : bytes(p), { status, headers });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.hostname.startsWith('www.')) {
      url.hostname = url.hostname.slice(4);
      return Response.redirect(url.toString(), 301);
    }
    if (url.pathname.startsWith('/api/estimate/') || url.pathname === '/admin/leads') {
      return handleEstimator(request, env);
    }
    if (isMediaPath(url.pathname)) return serveFilm(request, env, headersFor(url.pathname));
    return serveFile(request, url);
  },
};
